/*
   Problem 2. Turn on all LEDs one by one in a sequence and turn off in opposite sequence. (use some delay)
 */

#include <stdio.h>
#include "led.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	Init();
	while(1)
	{
		for(uint8_t i = 12; i <16; i++)
		{
			Led_On(i);
			DelayMs(500);
		}
		DelayMs(1000);
		for(uint8_t i = 15; i> 11; i--)
		{
			Led_Off(i);
			DelayMs(500);
		}
		DelayMs(1000);
	}

}
